import { ImageResponse } from 'next/og';

export const size = { width: 1200, height: 630 };
export const contentType = 'image/png';

// Logo incrustado como base64 para que Satori (el motor que genera esta imagen)
// no dependa de una petición de red externa en cada carga.
const LOGO_BASE64 =
  'data:image/png;base64,';

export default function OpengraphImage() {
  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 56,
          background: '#FAF8F3',
        }}
      >
        <img src={LOGO_BASE64} width={280} height={280} />
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <div style={{ fontSize: 64, fontWeight: 700, fontFamily: 'serif', color: '#1B5E3A', lineHeight: 1.1 }}>
            ARCHIVO
          </div>
          <div style={{ fontSize: 64, fontWeight: 700, fontFamily: 'serif', color: '#1B5E3A', lineHeight: 1.1 }}>
            BLANQUIVERDE
          </div>
          <div style={{ fontSize: 30, marginTop: 18, color: '#A9813C', fontStyle: 'italic' }}>
            Archivo histórico del Córdoba CF
          </div>
        </div>
      </div>
    ),
    { ...size }
  );
}
